/**
 * cone-browser.js
 * ---------------
 * The dependency-cone browser on the gpu_stack portfolio page, in plain
 * vanilla JS. A dependency cone is everything a target variable depends on,
 * upstream hop by upstream hop.
 *
 * It fetches docs/data/registry-cone.json (pre-generated by the
 * `export-graph-json` CLI subcommand) and renders the upstream cone of the
 * selected target as an expandable OS-styled tree.
 *
 * If the JSON fails to load (file:// or a network error), the panel shows an
 * informative notice instead of breaking.
 *
 * Keyboard: every interactive element is a <button>, so Tab, Enter, and
 * Space work without extra code.
 *
 * Accessibility: #cone-status is aria-live="polite"; toggled tree regions
 * use aria-expanded on the controlling button.
 *
 * Design rules obeyed:
 *   - Zero border-radius; depth via outset/inset borders.
 *   - Pixelify Sans for chrome labels; IBM Plex Mono for node names.
 *   - Gold badge for root inputs (accent-gold); muted badge for constants.
 *   - No em dashes in copy.
 */

(function () {
  "use strict";

  // -----------------------------------------------------------------------
  // Constants
  // -----------------------------------------------------------------------

  /** Path is relative to the page; works under any <base> that serves docs/. */
  var DATA_PATH = "data/registry-cone.json";

  /** Cap on children rendered per expanded node, so a huge cone cannot flood the view. */
  var MAX_CHILDREN = 60;

  // -----------------------------------------------------------------------
  // Module-level state
  // -----------------------------------------------------------------------

  /** The parsed JSON payload; null while loading and after a failed load. */
  var graphData = null;

  /** Name of the target variable whose cone is being shown. */
  var activeTarget = "econ.cost.per_token";

  /** Names of the nodes whose children row is currently open. */
  var openNodes = new Set();

  // -----------------------------------------------------------------------
  // DOM refs (populated by init())
  // -----------------------------------------------------------------------

  var statusEl = null;
  var treeEl = null;
  var targetButtons = null;

  // -----------------------------------------------------------------------
  // Data loading
  // -----------------------------------------------------------------------

  function loadData() {
    setStatus("Loading dependency data...");
    fetch(DATA_PATH)
      .then(function (resp) {
        if (!resp.ok) {
          throw new Error("HTTP " + resp.status + " fetching " + DATA_PATH);
        }
        return resp.json();
      })
      .then(function (data) {
        graphData = data;
        setStatus("Ready. " + Object.keys(data.nodes).length + " nodes loaded.");
        renderCone(activeTarget);
      })
      .catch(function (err) {
        var notice = createEl("div", "cone-notice");
        notice.textContent =
          "Dependency data could not be loaded. " +
          "Serve this page over HTTP to use the cone browser " +
          "(cd docs && python3 -m http.server 8080). " +
          "Error: " + err.message;
        setStatus("Load failed.");
        treeEl.replaceChildren(notice);
      });
  }

  // -----------------------------------------------------------------------
  // Rendering helpers
  // -----------------------------------------------------------------------

  function setStatus(text) {
    if (statusEl) {
      statusEl.textContent = text;
    }
  }

  function createEl(tag, className) {
    var el = document.createElement(tag);
    if (className) {
      el.className = className;
    }
    return el;
  }

  /**
   * List the direct parents of a node. In the edges array, an edge points
   * from a dependency to the variable it defines, so a node's parents are
   * the `from` ends of every edge whose `to` is this node.
   */
  function directParents(nodeName) {
    if (!graphData) {
      return [];
    }
    var parents = [];
    for (var i = 0; i < graphData.edges.length; i++) {
      if (graphData.edges[i].to === nodeName) {
        parents.push(graphData.edges[i].from);
      }
    }
    parents.sort();
    return parents;
  }

  /**
   * Render one node row as a <button> element.
   *
   * depth     - visual indent level (integer)
   * nodeName  - variable name string
   * isTarget  - true when this is the top-level target node
   */
  function makeNodeButton(depth, nodeName, isTarget) {
    var node = graphData && graphData.nodes[nodeName];
    var parents = directParents(nodeName);
    var hasParents = parents.length > 0;
    var isOpen = openNodes.has(nodeName);

    var btn = createEl("button", "cone-row");
    btn.type = "button";
    btn.setAttribute("data-cone-name", nodeName);
    if (hasParents) {
      btn.setAttribute("aria-expanded", String(isOpen));
    }
    // A node with no upstream deps gets no aria-expanded attribute at all.
    // Setting it to "false" would tell a screen reader there is hidden
    // expandable content when there is none.
    if (isTarget) {
      btn.setAttribute("aria-current", "true");
    }

    var indent = createEl("span", "cone-row-indent");
    indent.style.setProperty("--depth", String(depth));
    indent.setAttribute("aria-hidden", "true");

    var nameSpan = createEl("span", "cone-row-name");
    nameSpan.textContent = nodeName;

    var badge = null;
    if (node) {
      if (node.is_constant) {
        badge = createEl("span", "cone-badge is-const");
        badge.textContent = "const";
      } else if (node.is_root_input) {
        badge = createEl("span", "cone-badge");
        badge.textContent = "root";
      }
    }

    var meta = createEl("span", "cone-row-meta");
    if (node) {
      meta.textContent = node.units + " [" + node.scope + "]";
    }

    btn.appendChild(indent);
    btn.appendChild(nameSpan);
    if (badge) {
      btn.appendChild(badge);
    }
    btn.appendChild(meta);

    if (hasParents) {
      btn.addEventListener("click", function () {
        handleNodeToggle(nodeName, depth, btn);
      });
    }

    return btn;
  }

  /**
   * Forget the open state of every node inside a collapsed subtree. Without
   * this, re-expanding the subtree would restore stale open children.
   */
  function purgeDescendantsFromOpenNodes(container) {
    var buttons = container.querySelectorAll("[data-cone-name]");
    for (var i = 0; i < buttons.length; i++) {
      openNodes.delete(buttons[i].getAttribute("data-cone-name"));
    }
  }

  /**
   * Toggle the children of nodeName below its row button.
   */
  function handleNodeToggle(nodeName, depth, btn) {
    if (openNodes.has(nodeName)) {
      // Collapse.
      openNodes.delete(nodeName);
      btn.setAttribute("aria-expanded", "false");
      var next = btn.nextElementSibling;
      if (next && next.classList.contains("cone-children")) {
        // Forget nested open state before removing the DOM, so re-expanding
        // this node later starts with all children collapsed.
        purgeDescendantsFromOpenNodes(next);
        next.remove();
      }
    } else {
      // Expand.
      openNodes.add(nodeName);
      btn.setAttribute("aria-expanded", "true");

      var parents = directParents(nodeName);
      var container = createEl("div", "cone-children");

      var shown = Math.min(parents.length, MAX_CHILDREN);
      for (var i = 0; i < shown; i++) {
        var childBtn = makeNodeButton(depth + 1, parents[i], false);
        // Each child gets a stagger slot for the cascade-in animation;
        // the CSS caps how far the stagger grows.
        childBtn.style.setProperty("--i", String(i));
        container.appendChild(childBtn);
      }
      if (parents.length > MAX_CHILDREN) {
        var more = createEl("div", "cone-notice");
        more.style.padding = "5px 8px";
        more.textContent =
          "+" + (parents.length - MAX_CHILDREN) + " more dependencies not shown.";
        container.appendChild(more);
      }

      var sibling = btn.nextElementSibling;
      btn.parentNode.insertBefore(container, sibling);
    }
  }

  // -----------------------------------------------------------------------
  // Full cone render
  // -----------------------------------------------------------------------

  function renderCone(targetName) {
    if (!graphData) {
      return;
    }
    openNodes.clear();

    var node = graphData.nodes[targetName];
    if (!node) {
      var notice = createEl("div", "cone-notice");
      notice.textContent = "Variable not found in loaded data: " + targetName;
      treeEl.replaceChildren(notice);
      setStatus("Error: variable not found.");
      return;
    }

    var topBtn = makeNodeButton(0, targetName, true);
    treeEl.replaceChildren(topBtn);

    var parents = directParents(targetName);
    setStatus(
      targetName + ": " +
      parents.length + " direct upstream dependencies, scope=" + node.scope +
      ", units=" + node.units
    );
  }

  // -----------------------------------------------------------------------
  // Target tab switching
  // -----------------------------------------------------------------------

  function selectTarget(newTarget) {
    if (!graphData) {
      return;
    }
    activeTarget = newTarget;
    if (targetButtons) {
      targetButtons.forEach(function (btn) {
        var isCurrent = btn.getAttribute("data-cone-target") === newTarget;
        btn.setAttribute("aria-selected", String(isCurrent));
      });
    }
    renderCone(newTarget);
  }

  // -----------------------------------------------------------------------
  // Initialisation
  // -----------------------------------------------------------------------

  function init() {
    statusEl = document.getElementById("cone-status");
    treeEl = document.getElementById("cone-tree");
    targetButtons = document.querySelectorAll("[data-cone-target]");

    if (!statusEl || !treeEl) {
      // This page has no cone panel; there is nothing to set up.
      return;
    }

    targetButtons.forEach(function (btn) {
      btn.addEventListener("click", function () {
        selectTarget(btn.getAttribute("data-cone-target"));
      });
    });

    loadData();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
